const promUrl = 'http://prometheus:9090/api/v1/query';

// Consultas PromQL clave del entorno
const queries = {
  cpuUsagePct: '100 - (avg(rate(node_cpu_seconds_total{mode="idle"}[5m])) * 100)',
  ramUsagePct: '(1 - (node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes)) * 100',
  postgresConnections: 'pg_stat_activity_count',
  activeContainers: 'count(container_last_seen{name=~"gamer_.*|glpi.*|nextcloud.*"})'
};

const metrics = {};

for (const [key, q] of Object.entries(queries)) {
  try {
    const res = await fetch(`${promUrl}?query=${encodeURIComponent(q)}`);
    const data = await res.json();
    if (data.status === 'success' && data.data.result.length > 0) {
      const val = parseFloat(data.data.result[0].value[1]);
      metrics[key] = isNaN(val) ? 0 : parseFloat(val.toFixed(2));
    } else {
      metrics[key] = "Sin datos";
    }
  } catch (err) {
    metrics[key] = "Error de consulta";
  }
}

const fecha = new Date().toISOString().split('T')[0];

// Armar el prompt para la IA
const prompt = `Actúa como un SysAdmin Senior de Infraestructura y DevOps.
Analiza las siguientes métricas de telemetría extraídas de Prometheus para la plataforma "Red Social Gamer":

- Utilización promedio de CPU (Host): ${metrics.cpuUsagePct}%
- Utilización de Memoria RAM: ${metrics.ramUsagePct}%
- Conexiones concurrentes a PostgreSQL: ${metrics.postgresConnections}
- Contenedores Docker activos monitoreados: ${metrics.activeContainers}

Genera un INFORME EJECUTIVO DE RENDIMIENTO en formato Markdown profesional que incluya:
1. Resumen Ejecutivo del estado de salud de la plataforma.
2. Diagnóstico de Capacidad y potenciales cuellos de botella.
3. Recomendaciones de optimización preventiva (Base de Datos, Memoria y Contenedores).
4. Conclusión y semáforo de estado (Verde / Amarillo / Rojo).

Fecha del informe: ${fecha}. Formato Markdown limpio sin rodeos.`;

return [{
  json: {
    fecha,
    metrics,
    prompt
  }
}];

const response = $input.first().json;
const fecha = $('Recolectar Metricas').item.json.fecha;

// Extraer el texto generado por Gemini
let reportMarkdown = "# Informe Ejecutivo de Rendimiento no disponible";
try {
  reportMarkdown = response.candidates[0].content.parts[0].text;
} catch (e) {
  reportMarkdown = `# Error al generar reporte con IA\n\nNo se pudo extraer el texto de Gemini: ${e.message}`;
}

const filename = `reporte_rendimiento_${fecha}.md`;

return [{
  json: {
    filename,
    reportContent: reportMarkdown,
    tamanoChars: reportMarkdown.length
  }
}];
